    if (closeTimerRef.current !== null) {
      window.clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }

  function openList() {
    if (disabled) {
      return;
    }
    clearCloseTimer();
    setRenderList(true);
    setExpanded(true);
  }

  function closeList({ restoreFocus = false } = {}) {
    setExpanded(false);
    setListVisible(false);
    clearCloseTimer();
